/* §1  config                                                             */
/* ===================================================================== */

enum {
    SIM_FPS_MIN         =  10,
    SIM_FPS_DEFAULT     =  60,
    SIM_FPS_MAX         = 240,
    SIM_FPS_STEP        =  10,

    SPEED_MIN           =   1,
    SPEED_DEF           =   8,
    SPEED_MAX           =  64,

    HUD_COLS            =  80,
    FPS_UPDATE_MS       = 500,

    /* Per-maze cell limits.  Outer max 16×8 = 128 cells; inner max
     * 16×8 = 128. Generous bounds; patterns use far less. */
    MAX_MAZE_W          =  16,
    MAX_MAZE_H          =   8,
    MAX_MAZE_CELLS      = MAX_MAZE_W * MAX_MAZE_H,

    /* Outer cell limit for the inner-maze pool. With a 16×8 outer
     * maze, that's 128 inner mazes. */
    MAX_OUTER_CELLS     = MAX_MAZE_W * MAX_MAZE_H,

    /* Color pair indices.  PAIR_HUD/PAIR_HINT reserved per CLAUDE.md. */
    PAIR_HUD            =   1,
    PAIR_HINT           =   2,
    PAIR_RAMP_BASE      =   3,    /* +0..+7 = 8 brightness/colour tints */
    PAIR_HOT            =  11,
    PAIR_COLD           =  12,
    PAIR_FLASH          =  13,
};

#define NS_PER_SEC      1000000000LL
#define NS_PER_MS          1000000LL
#define TICK_NS(f)      (NS_PER_SEC / (f))

#define ASPECT_Y_F           2.0f

/* Brightness fBm parameters — slow drift over the static mazes. */
#define BRIGHT_SCALE_X       0.040f
#define BRIGHT_SCALE_Y       0.080f
#define WIND_X_BASE          3.0f
#define FBM_OCTAVES          3

/* Wall bit positions. */
#define WALL_N               0x1u
#define WALL_E               0x2u
#define WALL_S               0x4u
#define WALL_W               0x8u

/* Ramp slot for outer vs inner walls — both chosen from the BRIGHT
 * half of the ramp so the inner stays visible even when the brightness
 * fBm field is at its dim end. INNER_RAMP=5 (was 3) ensures the
 * inner walls don't disappear; OUTER_RAMP=7 keeps the outer
 * dominant. Inner walls additionally never go to A_DIM (see the
 * `no_dim` flag in draw_wall_cell) — they're always at least
 * A_NORMAL so the inner-maze structure is always readable. */
#define OUTER_RAMP           7
#define INNER_RAMP           5

/*
 * Pattern enum — different (outer, inner) maze size combos.
 */
typedef enum {
    PATTERN_CLASSIC = 0,
    PATTERN_WIDE    = 1,
    PATTERN_DENSE   = 2,
    PATTERN_EVEN    = 3,
    N_PATTERNS      = 4,
} Pattern;

typedef struct {
    int outer_w, outer_h;
    int inner_w, inner_h;
} PatternCfg;

static const PatternCfg PATTERN_CFG[N_PATTERNS] = {
    /*               outer  inner */
    [PATTERN_CLASSIC] = { 6, 3,   6, 4 },
    [PATTERN_WIDE   ] = { 4, 2,  10, 6 },
    [PATTERN_DENSE  ] = { 8, 4,   4, 3 },
    [PATTERN_EVEN   ] = { 5, 3,   8, 5 },
};

static const char *pattern_name(Pattern p)
{
    switch (p) {
    case PATTERN_CLASSIC: return "CLASSIC";
    case PATTERN_WIDE:    return "WIDE   ";
    case PATTERN_DENSE:   return "DENSE  ";
    case PATTERN_EVEN:    return "EVEN   ";
    default:              return "?      ";
    }
}

/* GlyphSet — wall rendering style. */
typedef enum {
    GLYPH_LINES  = 0,
    GLYPH_BLOCKS = 1,
    GLYPH_MIXED  = 2,
    N_GLYPH_SETS = 3,
} GlyphSet;

static const char *glyph_set_name(GlyphSet g)
{
    switch (g) {
    case GLYPH_LINES:  return "lines";
    case GLYPH_BLOCKS: return "block";
    case GLYPH_MIXED:  return "mixed";
    default:           return "?    ";
    }
}

/* WallStyle — three glyphs that describe how to draw a maze level. */
typedef struct {
    char h_wall;     /* horizontal-segment glyph */
    char v_wall;     /* vertical-segment glyph   */
    char corner;     /* intersection glyph       */
} WallStyle;

static const WallStyle STYLE_LINES  = { '-', '|', '+' };
static const WallStyle STYLE_BLOCKS = { '#', '#', '#' };

static WallStyle outer_style_for(GlyphSet g)
{
    switch (g) {
    case GLYPH_LINES:  return STYLE_LINES;
    case GLYPH_BLOCKS: return STYLE_BLOCKS;
    case GLYPH_MIXED:  return STYLE_BLOCKS;
    default:           return STYLE_LINES;
    }
}

static WallStyle inner_style_for(GlyphSet g)
{
    switch (g) {
    case GLYPH_LINES:  return STYLE_LINES;
    case GLYPH_BLOCKS: return STYLE_BLOCKS;
    case GLYPH_MIXED:  return STYLE_LINES;
    default:           return STYLE_LINES;
    }
}

